"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Un écart début / fin fait de la patte une patte partielle. Les autres profils fermés de l’esquisse deviennent des découpes dans la plaque. Perçages et fenêtres dans une patte : centre le long de l’arête (sur une arête courbe, le long de l’arc), centre à partir de la fin du pli, taille – ils apparaissent aussi dans le développé. Lorsqu’une arête courbe se prolonge sans angle dans son arête voisine et que les deux portent une patte avec le même angle de pli, les pattes se rejoignent sans découpe de dégagement. « Contour d’esquisse » découpe dans la patte les profils fermés d’une esquisse : son X suit l’arête, son Y va vers l’intérieur de la patte, l’origine se trouve au début de l’arête, à la fin du pli (déplaçable).",
