"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Sélectionnez toutes les faces à faire disparaître (pour une poche, les parois et le fond ; pour un perçage, la paroi ; pour un congé, la face arrondie). Les faces voisines sont prolongées au-dessus de la lacune. L'étape est recalculée lors des modifications du corps ; au premier usage, le noyau géométrique complet est chargé (quelques secondes).",
