"Bei Kanten einer gewählten Fläche wird der erste Abstand auf dieser Fläche gemessen.":"Pour les arêtes d'une face sélectionnée, la première distance est mesurée sur cette face.",
"Bei den markierten Operationen noch Flächen im Modell wählen.":"Pour les opérations marquées, il reste à choisir des faces dans le modèle.",
"Bei „Bohrungen“ liegt das Teil auf der Fläche an dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Avec « Perçages », la pièce repose sur la face, à l'extrémité du perçage la plus proche du point cliqué. Cliquer sur plusieurs perçages l'un après l'autre, puis sur « Terminé ».",
"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Avec « Perçages », la pièce se place à fleur dans l'extrémité du perçage la plus proche du point cliqué. Cliquer sur plusieurs perçages l'un après l'autre, puis sur « Terminé ».",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"Avec « Perçages », la tête se place du côté du perçage le plus proche du point cliqué ; la tige pénètre dans le perçage. Cliquer sur plusieurs perçages l'un après l'autre, puis sur « Terminé ».",
