"Draufsicht je Ebene: oben = hinten (+Y), rechts = +X":"Vue de dessus par niveau : haut = arrière (+Y), droite = +X",
"Dreh-Setup mit Fräs-Postprozessor – bitte einen Dreh-Postprozessor wählen.":"Configuration de tournage avec un post-processeur de fraisage – veuillez choisir un post-processeur de tournage.",
"Drehachse":"Axe de rotation",
"Drehbearbeitung: Kontur aus dem Modell (Drehachse = Setup-Z).":"Tournage : contour issu du modèle (axe de rotation = Z de la configuration).",
"Drehen":"Tournage",
"Drehen - Bohren":"Tournage - alésage",
"Drehen - Einstechen":"Tournage - gorge",
"Drehen - Gewinde":"Tournage - filetage",
"Drehen - allgemein":"Tournage - général",
