"Drehen um die Kappe":"Tourner autour du capuchon",
"Drehen umkehren":"Inverser la rotation",
"Drehen: C-Achse und angetriebenes Werkzeug ein":"Tournage : axe C et outil entraîné activés",
"Drehen: Das Teil muss rotationssymmetrisch um die Z-Achse liegen. Z0 = Planfläche oben, X = Durchmesser.":"Tournage : la pièce doit être de révolution autour de l'axe Z. Z0 = face frontale en haut, X = diamètre.",
"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Rotation : cliquer sur le centre de rotation, puis indiquer l'angle avec la souris (aperçu). Échap termine.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Tournage : diamètre auquel la tourelle indexe (Okuma, LinuxCNC). 0 = Ø du brut + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Rotation : sélectionnez des éléments, puis cliquez sur le centre de rotation et indiquez l'angle à la souris (aperçu) ; aussi en copie",
"Drehen: Gewindeschnitt":"Tournage : passe de filetage",
"Drehen: Gewindezyklus":"Tournage : cycle de filetage",
"Drehen: Polar-Interpolation aus":"Tournage : interpolation polaire désactivée",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Tournage : interpolation polaire activée (X diamètre, C en mm ; vide = X/C en degrés)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Tournage : cycle de finition (contour du cycle d'ébauche)",
"Drehen: Schruppzyklus ({contour} = Konturzeilen)":"Tournage : cycle d'ébauche ({contour} = lignes de contour)",
"Drehen: Vorsatz erste Konturzeile":"Tournage : préfixe de la première ligne de contour",
"Drehen: Vorsatz letzte Konturzeile":"Tournage : préfixe de la dernière ligne de contour",
"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"Rotation : angle (°, sens antihoraire) ; centre de rotation X ; centre de rotation Y ; copies (0 = tourner)",
"Drehen: Y-Achse aus":"Tournage : axe Y désactivé",
"Drehen: Y-Achse ein (Ebene X/Y; hier auch die C-Klemmung der Maschine eintragen)":"Tournage : axe Y activé (plan X/Y ; indiquer ici aussi le serrage C de la machine)",
"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Tournage : Z devant la face frontale auquel la tourelle indexe. 0 = distance de sécurité + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Tournage : interpolation cylindrique désactivée",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Tournage : interpolation cylindrique activée ({cylr} = rayon ; vide = Z/C sans)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Tournage : outil entraîné et axe C désactivés",
"Drehen: einen Winkel angeben.":"Rotation : indiquer un angle.",
"Drehgelenk":"Pivot",
"Drehgelenk angelegt – mit dem Regler bewegen.":"Pivot créé – le déplacer avec le curseur.",
"Drehgeschwindigkeit":"Vitesse de rotation de la vue",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Tour avec axe Y : les méplats de clé, contours et poches sur la face sont usinés avec la pièce immobile (C fixe) en X et Y – plus précis que l'interpolation polaire. Ce qui dépasse la course Y reste en interpolation polaire.",
