"Drücken/Ziehen geht bei ebenen Flächen – für Kanten die Kante anklicken.":"Appuyer/Tirer fonctionne sur les faces planes – pour les arêtes, cliquez sur l'arête.",
"Drücken/Ziehen: ebene Fläche anklicken (verschieben) oder Kante anklicken (verrunden).":"Appuyer/Tirer : cliquez sur une face plane (déplacer) ou sur une arête (congé).",
"Dunkel":"Sombre",
