"Durchgangspunkte klicken. Auf den Startpunkt klicken schließt die Spline, Enter beendet sie offen.":"Cliquez les points de passage. Cliquer sur le point de départ ferme la spline, Entrée la termine ouverte.",
"Durchgehend":"Traversant",
"Durchgereichter NC-Code wird unverändert ausgegeben und nicht geprüft – er muss zur Steuerung passen und darf das Werkzeug nicht in eine unbekannte Lage bringen":"Le code NC transmis est sorti tel quel et n'est pas vérifié – il doit convenir à la commande et ne doit pas amener l'outil dans une position inconnue",
"Durchgänge":"Passes",
"Durchlaufender Radius: Die gewählten Kanten müssen eine zusammenhängende Kette bilden":"Rayon continu : les arêtes sélectionnées doivent former une chaîne continue",
