"Durchzug":"Collerette",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Collerette {0} : l'avant-trou Ø {1} mm est élargi à Ø {2} mm (facteur {3}) – le bord se fissure alors le plus souvent.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Collerette {0} : l'avant-trou Ø {1} mm est élargi à Ø {2} mm (facteur {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Collerette {0} : se trouve à {1} mm du bord (moins de 2 × l'épaisseur de tôle) – le bord se bombe.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Collerette {0} : trop haute pour ce perçage (l'avant-trou n'aurait plus de diamètre)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Collerette : le bord d'un perçage rond est relevé en collet, par exemple comme collerette taraudée. Le diamètre de perçage de l'esquisse est le diamètre intérieur fini ; dans le flan, c'est l'avant-trou plus petit qui est découpé.",
