"Eigene Kopie „{0}“ angelegt{1} (auch in der Bibliothek) – der eingebaute Postprozessor bleibt unverändert":"Copie personnelle « {0} » créée{1} (aussi dans la bibliothèque) – le post-processeur intégré reste inchangé",
"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Raccourcis personnalisés : ouvrir le menu du groupe (▾) dans la barre d'outils, cliquer sur ⋮ à côté de la commande → « Modifier le raccourci clavier … ».",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Les cotes et notes personnalisées se déplacent à la souris sur la feuille (distance de la ligne de cote, angle de la ligne de repère, rayon de l'arc d'angle). Cliquer deux coins = cote de longueur. Cliquer le bord d'un cercle dans la vue de dessus = diamètre (ou rayon). Angle : d'abord le sommet, puis un point sur chaque côté. Chanfrein : les deux extrémités de l'arête oblique – donne p. ex. 2×45°. Le champ de texte après chaque cote contient un complément tel que ±0,1, H7 ou 4×.",
