"Ein geschlossenes Netz in einen Volumenkörper umwandeln (jedes Dreieck wird eine Fläche)":"Convertir un maillage fermé en corps volumique (chaque triangle devient une face)",
"Ein runder Fräser lässt in jeder Innenecke seinen Radius stehen – ein eckiges Gegenstück passt dann nicht hinein. Der Freistich fährt an jeder scharfen Innenecke kurz in die Ecke und zurück.{0}{1}":"Une fraise ronde laisse son rayon dans chaque angle intérieur – une pièce d'appui à angle vif ne s'y insère alors pas. Le dégagement va brièvement dans l'angle puis revient à chaque angle intérieur vif.{0}{1}",
