"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Le lissage nécessite deux esquisses à profils fermés sur des plans différents.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Le lissage nécessite deux esquisses d'une courbe chacune (sur des plans différents).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Lissage impossible – vérifier les sections (un profil fermé chacune, non vrillé)",
"Erhebung nicht möglich – je Skizze eine Kurve, gleiche Richtung, nicht verdreht":"Lissage impossible – une courbe par esquisse, même sens, non vrillée",
"Ersetzt den Standard-Kurzbefehl „{0}“.":"Remplace le raccourci par défaut « {0} ».",
"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Cliquez d'abord sur la face du corps à déplacer, puis sur la face cible de l'autre corps. Le corps est tourné et déplacé jusqu'à ce que le premier point de clic soit sur le second et que les faces soient en contact.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Cliquez d'abord sur l'arête du corps à déplacer, puis sur l'arête cible de l'autre corps. Les arêtes droites sont mises en coïncidence (milieu sur milieu) ; pour les arêtes circulaires – perçage et tenon – les axes sont alignés et les centres réunis.",
"Erst ein Setup anlegen.":"Créer d'abord une configuration.",
"Erst ein Setup mit Operationen anlegen.":"Créer d'abord une configuration avec des opérations.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Sélectionnez d'abord une esquisse ou un plan de construction – Ctrl+8 permet ensuite de les regarder perpendiculairement.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Créer d'abord un corps dans CONCEPTION ou insérer un maillage (STL).",
"Erst einen Körper in KONSTRUKTION erstellen.":"Créer d'abord un corps dans CONCEPTION.",
