"Fläche am bewegten Körper gewählt":"face du corps mobile sélectionnée",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Cliquez une face d’un corps : son bord est ajouté à l’esquisse comme contour. Cliquer une arête ne projette que cette arête (les cercles restent des cercles). La géométrie projetée est violette.",
"Fläche ersetzen":"Remplacer la face",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Remplacer la face : amener une face plane sur un autre plan – le corps s'allonge ou est raccourci",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Arrière-plan derrière les fenêtres – s’applique si le thème « Personnalisé » est choisi ci-dessus",
"Fläche löschen":"Supprimer la face",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Supprimer la face : retirer des perçages, poches, congés ou chanfreins – les faces voisines comblent le vide",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Afficher en couleur la face ou l'arête sous le pointeur",
"Fläche versetzen":"Décaler la face",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Décaler la face : déplacer des faces planes, modifier le diamètre des perçages et des tenons",
"Fläche wählen":"Sélectionner une surface",
"Fläche wählen, die getrimmt wird":"Choisir la surface à couper",
"Fläche zum Antasten in Z":"Face de palpage en Z",
"Fläche {0}":"Face {0}",
"Flächen":"Faces",
"Flächen (alle Kanten ringsum)":"Faces (toutes les arêtes du pourtour)",
"Flächen (aufeinander legen)":"Faces (les placer l'une sur l'autre)",
"Flächen am Körper":"Faces du corps",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Méplats en bout de pièce (deux plats, carré, hexagone) avec une fraise à queue tournante le long de Z. Largeur sur plats = double de la distance du méplat à l'axe de rotation. X et C se déplacent ensemble (interpolation polaire, Fanuc G12.1) ; sans ce modèle dans le post-processeur, de courts pas X/C sont sortis.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Cliquez sur les faces à épaissir (un nouveau clic les retire).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Cliquer les faces à dépouiller (un nouveau clic les retire).",
"Flächen anklicken, die offen sein sollen.":"Cliquer les faces à laisser ouvertes.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Cliquez sur les faces à décaler (un nouveau clic les retire).",
"Flächen im Modell":"Faces du modèle",
