"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Lignes droites de l'esquisse n'appartenant à aucun profil (lignes de construction comprises). Pli : la ligne est le milieu de la zone de pliage, l'esquisse y représente le flan – la plus grande partie de la plaque reste en place, tout ce qui est au-delà de la ligne pivote avec ses pattes. La ligne s'applique sur toute la plaque. Nervure : une côte le long de la ligne, ronde en section et aux extrémités ; la tôle conserve son épaisseur.",
