"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Fermé : les pattes sur deux arêtes voisines s'étendent jusqu'à la bissectrice du coin et y laissent le jeu. Le dégagement d'angle se situe là où les zones de pliage se croisent – dans le dépliage et dans la pièce pliée. Une patte sur une arête courbe est elle aussi coupée en onglet à un vrai coin (sans dégagement d'angle à cet endroit).",
