"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Les corps importés n'ont pas d'historique de conception, mais peuvent être retravaillés (congé, chanfrein, découpe …) et utilisés pour la FAO. Avec « Axe Y vers le haut », les modèles issus de logiciels dont l'axe Y pointe vers le haut sont correctement orientés.",
