"Installierte Windows-App und Linux-AppImage laden das Update selbst; sonst öffnet sich die Download-Seite":"L'application Windows installée et l'AppImage Linux téléchargent la mise à jour elles-mêmes ; sinon la page de téléchargement s'ouvre",
