"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"La première courbe de chaque esquisse – ouverte ou fermée. Les courbes sont reliées par une peau (surface sans épaisseur).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"Un fichier par plaque. La trajectoire longe le contour dans la chute, décalée d'une demi-largeur de coupe (au fraisage, d'un demi-rayon de fraise) ; les découpes passent avant le contour de leur pièce, chaque contour commence par une amorce depuis la chute. Mise en marche avec M3 (laser : M3 S…), arrêt avec M5, temps de perçage en G4. L'origine est le coin inférieur gauche de la plaque ; au fraisage, Z0 est le dessus de la tôle. Vérifier le programme sur la machine ou dans un simulateur CN avant l'emploi.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Chaque axe séparément : cliquez sur une arête, un coin, une face ou un perçage. Les axes non définis proviennent du point du brut.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Chaque opération comme sous-programme (LBL) en fin de programme, appel avec CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Chaque cercle de l'esquisse est un centre de perçage. Le perçage se fait à l'opposé de la normale de l'esquisse (dans la matière).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Chaque cercle de l'esquisse est répété par rotation autour du centre (en coordonnées de l'esquisse) – un cercle placé à la distance du rayon primitif donne un cercle de perçage.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Chaque cercle de l'esquisse devient une grille : espacements en X et Y de l'esquisse (négatifs possibles).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Cliquer maintenant un point sur le second côté.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Maintenant, chaque direction une fois jusqu'en butée : glisser, tirer, appuyer, incliner, tourner (10 s) …",
"Jetzt laden":"Télécharger maintenant",
"Jetzt nach Updates suchen":"Rechercher les mises à jour maintenant",
"K-Faktor":"Facteur K",
"K-Faktor {0} liegt außerhalb des üblichen Bereichs 0,25 … 0,5 – der Zuschnitt weicht dann meist vom gebogenen Teil ab.":"Le facteur K {0} est en dehors de la plage habituelle 0,25 … 0,5 – le flan s'écarte alors généralement de la pièce pliée.",
