"Kalibrieren …":"Calibrer …",
"Kalibrieren: einen Abstand größer als 0 angeben.":"Calibrer : indiquez une distance supérieure à 0.",
"Kalibrieren: ersten Punkt im Bild anklicken (Esc bricht ab).":"Calibrer : cliquez sur le premier point de l'image (Échap annule).",
"Kalibrieren: wirklicher Abstand der beiden Punkte (mm)":"Calibrer : distance réelle entre les deux points (mm)",
"Kalibrieren: zwei Punkte im Bild anklicken, deren Abstand bekannt ist, und den wirklichen Abstand eingeben – das Bild bekommt den richtigen Maßstab.":"Calibrer : cliquez sur deux points de l'image dont la distance est connue et saisissez la distance réelle – l'image reçoit la bonne échelle.",
"Kalibrieren: zweiten Punkt im Bild anklicken (Esc bricht ab).":"Calibrer : cliquez sur le deuxième point de l'image (Échap annule).",
