"Kante {0} ist zu kurz für eine Lasche":"L'arête {0} est trop courte pour un rabat",
"Kante {0}: Biegewinkel über 180° ist nicht herstellbar.":"Arête {0} : un angle de pliage supérieur à 180° n'est pas réalisable.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestaucht (Faltengefahr); der Zuschnitt ist dort eine Näherung.":"Arête {0} : patte sur une arête courbe – son bord est comprimé de {1} % lors du formage (risque de plis) ; le flan y est une approximation.",
"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Arête {0} : patte sur une arête courbe – son bord est étiré de {1} % lors du formage (risque de fissures) ; le flan y est une approximation.",
"Kante {0}: das Laschenmaß {1} mm ist kleiner als die Biegung ({2} mm)":"Arête {0} : la cote de la patte {1} mm est inférieure au pli ({2} mm)",
"Kante {0}: der Bogen ist zu eng für diese Lasche":"Arête {0} : l’arc est trop serré pour cette patte",
"Kante {0}: die Abstände lassen keine Lasche übrig.":"Arête {0} : les décalages ne laissent aucune bride.",
"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Arête {0} : la patte croise une ligne de pliage – la faire s'arrêter avant le pli avec « Décalage début / fin »",
"Kante {0}: die Lasche liegt in einer Biegezone":"Arête {0} : la patte se trouve dans une zone de pliage",
"Kante {0}: ein Ausschnitt gehört zu einer Lasche, die es nicht gibt.":"Arête {0} : une découpe appartient à une patte qui n'existe pas.",
"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Arête {0} : une découpe dans la patte se trouve à {1} mm du pli (moins de 2 × l'épaisseur de tôle) – elle se déforme lors du pliage.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Arête {0} : une découpe se trouve à {1} mm du pliage (moins de 2 × l'épaisseur de la tôle) – elle se déforme au pliage.",
"Kante {0}: ein Ausschnitt ragt über die Lasche hinaus.":"Arête {0} : une découpe dépasse de la patte.",
"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Arête {0}{1} : la bride de {2} mm est plus courte que 2 × l'épaisseur de la tôle – difficilement pliable sur la presse plieuse.",
"Kanten":"Arêtes",
"Kanten (Geraden deckungsgleich, Kreise mittig)":"Arêtes (droites coïncidentes, cercles concentriques)",
"Kanten anklicken (erneut klicken entfernt).":"Cliquez sur des arêtes (un nouveau clic les retire).",
"Kanten wählen":"Sélectionner des arêtes",
"Kanten wählen, die einen geschlossenen Rand bilden":"Choisir des arêtes formant un bord fermé",
"Kantenglättung":"Anticrénelage",
"Kantenhöhe":"Hauteur de l'arête",
"Kappe loslassen und „Nullpunkt kalibrieren“ wählen. Danach jede Richtung ausprobieren: der Balken soll sich bewegen, in Ruhe in der grauen Totzone bleiben.":"Relâcher le capuchon et choisir « Étalonner le point zéro ». Essayer ensuite chaque direction : la barre doit bouger et rester dans la zone morte grise au repos.",
"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Glisser le capuchon = déplacer, appuyer/tirer = zoomer, incliner et tourner = faire pivoter le modèle. Dans les esquisses, seulement déplacer et zoomer. SpaceMouse Pro/Enterprise : T, F, R = vue de dessus, de face, de droite. Si rien ne se passe : arrêter brièvement le pilote 3Dconnexion puis reconnecter.",
