"Kieme: die Linie ist ein Schlitz, das Blech daneben wird zu einer Haube aufgestellt, die an beiden Enden des Schlitzes in die Platte ausläuft (Lüftungsschlitz). Im Zuschnitt ist der Schlitz ein Schnitt.":"Persienne : la ligne est une fente, la tôle voisine est relevée en capot qui se raccorde à la plaque aux deux extrémités de la fente (ouïe de ventilation). Dans le flan, la fente est une découpe.",
