"Kontur mit {0} Punkten – Okuma: G85 (LAP) mit Kontur G81…G80, Fanuc: G71 P…Q…. Die Steuerung schruppt mit ihrer eigenen Aufteilung; die Simulation hier ist die WerkFab-Bahn.":"Contour de {0} points – Okuma : G85 (LAP) avec contour G81…G80, Fanuc : G71 P…Q…. La commande ébauche avec sa propre répartition des passes ; la simulation affichée ici est celle de WerkFab.",
