"Konturen außen und innen":"Contours extérieurs et intérieurs",
"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Les contours suivent le bord des zones sombres. La ligne médiane suit le milieu des traits – adaptée aux gravures et aux dessins au trait. « Droites, arcs et cercles » détecte les arêtes droites, les angles vifs, les arrondis et les cercles ; « Polylignes » suit l'image point par point. Ajustez ensuite l'échelle si nécessaire avec « Calibrer le modèle » ou « Mettre à l'échelle ».",
"Konturen mit Radiuskorrektur an der Steuerung (RL/RR) fahren mit APPR/DEP an und ab; die Steuerung berechnet Hilfspunkt und Korrektur selbst":"Les contours avec correction de rayon dans la commande (RL/RR) sont abordés et quittés avec APPR/DEP ; la commande calcule elle-même le point auxiliaire et la correction",
