"Kurven":"Courbes",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Courbes d'une esquisse sur la face frontale (transversale à l'axe de rotation) avec une fraise tournante le long de Z (X et C se déplacent ensemble ; Fanuc : interpolation polaire G12.1). Les courbes ouvertes sont fraisées aller et retour. Profondeur à partir de la face frontale.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Les courbes d'une esquisse située le long de l'axe de rotation sont enroulées sur la circonférence et fraisées avec une fraise tournante dirigée vers l'axe (Z et C se déplacent ensemble ; Fanuc : interpolation cylindrique G7.1). Le plan d'esquisse détermine l'angle où se situe le contour ; les segments horizontaux de l'esquisse deviennent des arcs autour de la pièce. Profondeur à partir du diamètre extérieur.",
"Kurzbefehl":"Raccourci",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Les courts déplacements (jusqu'à la distance de maintien) sont effectués en bas à l'avance de transition au lieu de passer par la hauteur de retrait – sans contrôle de collision, donc à garder petit.",
