"Material":"Matériau",
"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Choisir le matériau dans la configuration sous « Brut → Matériau du brut ». La densité donne le poids du brut, Vc est une valeur indicative pour le carbure ; la couleur est celle de la simulation.",
"Material wählen":"Choisir le matériau",
"Materialeinfahrt":"Rampe d'entrée",
"Materialien über „Darstellung“ (A) auf die Körper ziehen. Beim In-Canvas-Rendern wird das Bild mit jedem Durchgang glatter (weiche Schatten, saubere Kanten); jede Kamerabewegung beginnt neu.":"Glissez les matériaux sur les corps via « Apparence » (A). Lors du rendu dans la vue, l'image s'affine à chaque passe (ombres douces, arêtes nettes) ; chaque mouvement de caméra recommence le calcul.",
