"Maße, Hinweise und Toleranzen lassen sich auch in einer Detailansicht setzen – sie zeigen die wahren Größen.":"Les cotes, notes et tolérances peuvent aussi être placées dans une vue de détail – elles indiquent les dimensions réelles.",
