"Maßstab {0} · {1} Bohrung(en) erkannt · Projektionsmethode 1 (DIN ISO 128). Ansichten lassen sich mit der Maus auf dem Blatt verschieben.":"Échelle {0} · {1} perçage(s) détecté(s) · méthode de projection 1 (DIN ISO 128). Les vues se déplacent à la souris sur la feuille.",
