"Mehrere Schlichtdurchgänge":"Plusieurs passes de finition",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Plusieurs arêtes consécutives comptent comme un seul parcours : le rayon varie du début à la fin de la chaîne, les points de contrôle sont en % de la longueur totale de la chaîne. Ce calcul est effectué par le noyau géométrique complet.",
