"Mit Beispielprojekt starten":"Démarrer avec un projet exemple",
"Mit Gelenken duplizieren":"Dupliquer avec les liaisons",
"Mit Körper verbinden":"Fusionner avec le corps",
"Mit Netzkörper":"Avec le corps maillé",
"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Avec des points de contrôle, le rayon passe par les valeurs indiquées (position en % de la longueur de l'arête). Ce calcul est effectué par le noyau géométrique complet ; au premier usage, son chargement prend quelques secondes.",
"Mit dem 3D-Taster kann nicht zerspant werden":"Le palpeur 3D ne peut pas servir à usiner",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Comparer avec la pièce finie : vert = à la cote, bleu = matière restante, rouge = trop profond",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Placer la souris à côté d'un contour (le côté détermine le sens) · Échap termine",
"Mit diesem Werkzeug kann nicht gefräst werden":"Cet outil ne permet pas de fraiser",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"Avec un taraud, utiliser uniquement le cycle « Taraudage » – un cycle de perçage le casserait",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Avec plusieurs passes, la profondeur du filetage est fraisée par étapes enlevant chacune à peu près la même quantité – cela ménage les petites fraises à fileter et les matériaux durs. La passe à blanc reparcourt la dernière trajectoire sans passe supplémentaire.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Avec « Cycles de perçage » dans le programme CN, des cycles de la commande sont sortis (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sinon des déplacements détaillés.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Avec « Conserver l'original », l'original et son image symétrique forment un seul maillage ; les points situés sur le plan de symétrie sont reliés – une moitié ouverte devient ainsi une pièce fermée.",
