"Nichts getroffen – Kante, Ecke, Fläche oder Bohrung anklicken.":"Rien de sélectionné – cliquez sur une arête, un sommet, une face ou un perçage.",
"Nichts getroffen – auf das Modell klicken.":"Rien de sélectionné – cliquez sur le modèle.",
