"Nichts gewählt – „Auswählen“, dann Flächen oder Kanten im Modell anklicken.":"Rien de sélectionné – « Sélectionner », puis cliquez sur des faces ou des arêtes du modèle.",
"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"Rien n'a changé : les faces voisines ne ferment pas cette lacune – sélectionner ensemble les faces qui vont ensemble (p. ex. paroi et fond d'une poche)",
