"Nur Außenkonturen":"Contours extérieurs uniquement",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Seuls les contours extérieurs (tenons) sont possibles en cycle de la commande",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Diamètre seul (forme identique à cet outil)",
"Nur Innenkonturen (Öffnungen)":"Contours intérieurs uniquement (ouvertures)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Seules les poches rectangulaires et circulaires sont possibles en cycle de la commande",
"Nur Skizze":"Esquisse seule",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"N'usiner que ce qu'une fraise plus grande a laissé dans les angles.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Ne repasser que sur les parties du contour qu'une fraise plus grande n'a pas atteintes (angles intérieurs, zones étroites). Sans arcs d'approche/de sortie, ponts de maintien ni passes de finition ; correction dans l'ordinateur.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Uniquement là où l'outil de référence n'est pas passé : zones plates en parallèle, zones raides en lignes de niveau. Avec un outil de la liste, sa forme est prise en compte – par exemple ce qu'une fraise torique laisse dans les congés.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Seules les faces planes peuvent servir de plan d'esquisse.",
"Nur ebene Flächen können extrudiert werden":"Seules les faces planes peuvent être extrudées",
"Nur ebene Flächen lassen sich ersetzen":"Seules les faces planes peuvent être remplacées",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Seules les faces planes et cylindriques (perçages, tourillons) peuvent être décalées",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Uniquement les faces planes tournées vers le haut, vers l'outil (horizontales dans cette configuration).",
"Nur für Außen-Drehmeißel":"Uniquement pour outils de tournage extérieurs",
"Nur in Operationen verwendete":"Uniquement ceux utilisés dans des opérations",
"Nur in diesem Projekt":"Uniquement dans ce projet",
"Nur mit Korrektur „Im Rechner“.":"Uniquement avec la correction « Dans le calculateur ».",
