"Nut":"Rainure",
"Nut angetrieben":"Rainure outil tournant",
"Nut angetrieben (C-Achse)":"Rainure avec outil tournant (axe C)",
"Nut liegt nicht am Teil":"La rainure n'est pas sur la pièce",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Rainure le long de l'axe de rotation (p. ex. rainure de clavette) avec une fraise tournante dirigée vers l'axe ; la broche principale maintient la pièce en axe C. Largeur de rainure = Ø de fraise. Début/fin Z en Z du modèle ; si la rainure atteint la face frontale, la fraise entre par l'avant, sinon elle plonge au départ. Profondeur à partir du diamètre extérieur.",
"Nutbreite bei Linien":"Largeur de rainure pour les lignes",
