"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Les arêtes ouvertes sont affichées en rouge. « Réparer » ferme les trous.",
"Offene Linie in einer Skizze wählen":"Choisir une ligne ouverte dans une esquisse",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Les courbes ouvertes ou fermées sont extrudées perpendiculairement à l'esquisse – le résultat est une surface (paroi sans épaisseur). « Épaissir » ou « Assembler » la transforme en volume.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Les courbes ouvertes ou fermées sont tournées autour de l'axe – le résultat est une surface, pas un volume.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Sans touche personnalisée, la valeur par défaut « {0} » s'applique.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Sans « Modélisé », le filetage est seulement représenté (rapide). En mode modélisé, la forme du filetage est réellement découpée, p. ex. pour l'impression 3D. Perçage pour M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP tournage",
"Okuma OSP-M Fräsen":"Okuma OSP-M fraisage",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP : G28/G53 n'y vont pas aux coordonnées machine (G53 annule la correction de longueur d'outil) – dégagement à la hauteur de sécurité, aucune prise de référence XY sortie",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP : aucune fonction de lissage sortie (G5.1 est Fanuc) – régler Hi-Cut/Super-NURBS sur la machine",
