"OpenCascade (alle Funktionen)":"OpenCascade (toutes les fonctions)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade : toutes les fonctions. Noyau Rust (truck, expérimental) : primitives, extrusion, révolution, perçage, réseau, symétrie, déplacement, mise à l'échelle, combinaison et export STEP – les autres fonctions sont signalées comme « pas encore prises en charge ».",
