"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Positif = vers l'extérieur (plus de matière), négatif = vers l'intérieur. Les faces planes se déplacent ; pour un perçage ou un tenon, le rayon varie de la valeur de la distance – un perçage se rétrécit avec une distance positive.",
"Positiver Abstand = in Richtung der Skizzennormalen. Taschen: Ausschneiden mit negativem Abstand.":"Distance positive = dans le sens de la normale à l’esquisse. Poches : enlèvement avec une distance négative.",
