"Projizieren (J): Fläche oder Kante eines Körpers anklicken – ihr Abbild kommt in die Skizze":"Projeter (J) : cliquez sur une face ou une arête d'un corps – sa projection est ajoutée à l'esquisse",
"Projizieren von Kanten und Flächen braucht einen Volumenkörper des Standardkerns – Körperumriss und Schnittkurven gehen auch bei Netzen.":"La projection d'arêtes et de faces nécessite un corps volumique du noyau standard – la silhouette du corps et les courbes d'intersection fonctionnent aussi avec les maillages.",
