"Prägung":"Gaufrage",
"Prägung {0}: die Kontur ist schmaler als 2 × Blechdicke – es bleibt kein Hohlraum.":"Gaufrage {0} : le contour est plus étroit que 2 × l'épaisseur de tôle – aucune cavité ne subsiste.",
"Prägung {0}: lässt sich so nicht formen":"Gaufrage {0} : ne peut pas être formé ainsi",
"Prägung {0}: {1} mm ist höher als 3 × Blechdicke – mit senkrechter Wand reißt das Blech.":"Gaufrage {0} : {1} mm dépasse 3 × l'épaisseur de tôle – avec une paroi verticale, la tôle se déchire.",
"Prägung: die Kontur wird nicht ausgeschnitten, sondern um die Höhe aus der Platte gedrückt. Senkprägung: der Rand einer runden Bohrung wird zu einem 90°-Kegel gedrückt – für Senkschrauben in dünnem Blech (− nach unten: Schraube von oben).":"Gaufrage : le contour n'est pas découpé mais repoussé hors de la plaque de la hauteur indiquée. Fraisure emboutie : le bord d'un perçage rond est repoussé en cône à 90° – pour vis à tête fraisée dans une tôle mince (− vers le bas : vis par le dessus).",
