"Tasche Mantelfläche (C-Achse)":"Poche sur diamètre (axe C)",
"Tasche Planfläche":"Poche en face",
"Tasche Planfläche (C-Achse)":"Poche sur face frontale (axe C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Poche sur la circonférence à partir des contours fermés d'une esquisse placée dans le sens de l'axe de tournage (les contours intérieurs subsistent comme îlots). L'esquisse est enroulée sur le diamètre ; une fraise 2 tailles motorisée dirigée vers l'axe ébauche de l'intérieur vers l'extérieur (Z et C se déplacent ensemble ; Fanuc : interpolation cylindrique G7.1). La fraise plonge en rampe le long de l'anneau le plus intérieur.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Poche dans la face frontale à partir des contours fermés d'une esquisse (les contours intérieurs subsistent comme îlots), avec une fraise à queue tournante le long de Z. Le dégagement va de l'intérieur vers l'extérieur ; la fraise plonge en rampe le long de la trajectoire la plus interne et reste en bas au sein d'un niveau. X et C se déplacent ensemble (Fanuc : interpolation polaire G12.1). Profondeur à partir de la face frontale.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Poche avec îlot – le cycle de la commande ne gère pas les îlots",
"Tasche schmaler als das Werkzeug":"Poche plus étroite que l'outil",
