"Toleranzwert, dahinter die Bezüge (durch Leerzeichen getrennt), z. B. Ø0,05 A B. Zusätze in Klammern werden als Buchstabe im Kreis gezeichnet: Ø0,05(M) A(M) – (M) Maximum-Material, (L) Minimum-Material, (P) projiziert, (F) freier Zustand, (E) Hüllbedingung":"Valeur de tolérance suivie des références (séparées par des espaces), p. ex. Ø0,05 A B. Les compléments entre parenthèses sont dessinés comme une lettre dans un cercle : Ø0,05(M) A(M) – (M) maximum de matière, (L) minimum de matière, (P) projetée, (F) état libre, (E) exigence de l'enveloppe",
