"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Calcule réellement l’opération entre deux maillages fermés : les faces situées à l’intérieur disparaissent, les arêtes d’intersection sont remaillées. Le calcul ne porte que sur la zone où les deux maillages peuvent se rencontrer – un grand maillage avec une petite intervention est donc rapide. Si deux grands maillages se chevauchent entièrement, utilisez d’abord « Réduire ».",
