"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Enroule les courbes de l'esquisse sur le cylindre : X reste X, la distance transversale à l'axe devient un arc sur le Ø de développement (rotation A). L'esquisse doit être parallèle à l'axe A, p. ex. sur un plan tangent. Le fraisage se fait à profondeur constante sous la surface de la pièce – pour gravures, inscriptions et rainures autour de la pièce.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Comme le contour 3D, mais l'outil descend en continu sans paliers – pas de marques de plongée sur les parois raides.",
