"{0}: Fläche oder Kante im Modell anklicken.":"{0} : cliquez sur une face ou une arête du modèle.",
"{0}: GRBL kennt keine Radiuskorrektur (G41/G42) – Bahn ohne Korrektur ausgegeben":"{0} : GRBL ne gère pas la compensation de rayon (G41/G42) – trajectoire sortie sans compensation",
"{0}: Nullpunkt Y/Z liegt nicht auf der Drehachse A (Achse bei Y{1} Z{2}) – für 4-Achs-Simultan den Nullpunkt auf die Achse legen (Rohteil-Punkt Mitte Y/Z)":"{0} : l'origine pièce Y/Z n'est pas sur l'axe de rotation A (axe en Y{1} Z{2}) – pour le 4 axes simultané, placer l'origine pièce sur l'axe (point du brut centre Y/Z)",
"{0}: Postprozessor ohne Drehzyklus – als Bahn ausgegeben":"{0} : post-processeur sans cycle de tournage – sorti comme trajectoire",
"{0}: Postprozessor ohne Polar-Interpolation – Flächen als kurze X/C-Schritte (C in Grad) ausgegeben; der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Polar-Interpolation ein/aus“ eintragen":"{0} : post-processeur sans interpolation polaire – faces sorties en petits pas X/C (C en degrés) ; selon la commande, l'avance ne s'applique alors pas le long de la trajectoire. Il vaut mieux renseigner le modèle « Interpolation polaire activée/désactivée »",
"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0} : post-processeur sans modèle « Axe C et outil entraîné activés » – activer l'axe C et la broche d'outil manuellement",
"{0}: Postprozessor ohne Zylinder-Interpolation – Z und C fahren gemeinsam, der Vorschub gilt dann je nach Steuerung nicht entlang der Bahn. Besser die Vorlage „Zylinder-Interpolation ein/aus“ eintragen":"{0} : post-processeur sans interpolation cylindrique – Z et C se déplacent ensemble ; selon la commande, l'avance ne s'applique alors pas le long de la trajectoire. Il vaut mieux renseigner le modèle « Interpolation cylindrique activée/désactivée »",
