"{0}: Steuerung/Postprozessor ohne Gewindebohrzyklus – als Vorschubbewegung ausgegeben (nur mit Ausgleichsfutter!)":"{0} : commande/post-processeur sans cycle de taraudage – sorti en déplacement d'avance (uniquement avec mandrin de compensation !)",
