"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"« + » = l'outil sera créé. Les données de coupe sont des valeurs indicatives pour le carbure ({0}){1} ; arrosage : {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"« Imbriquer les flans » place les flans dans les vides et les renfoncements de leurs voisins ainsi que dans leurs découpes (sans rotation de 90°, seulement retournés de 180°) ; l’écart n’est jamais réduit. Sans la coche, ils sont disposés en rangées selon leur rectangle englobant. Avec « Esquisse + corps », on obtient des corps plats à l’épaisseur de la tôle, qui peuvent être découpés en fabrication avec un contour 2D.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"« Intérieur/Extérieur » nécessite des contours fermés – usiner les courbes ouvertes avec « Sur la courbe »",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"« Terminer l’esquisse » → Extrusion, Révolution ou Perçage.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"« Esquisse » → choisir le plan XY/XZ/YZ ou cliquer sur une face plane.",
