"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ Vérifier chaque programme CN avant son premier lancement : sur la machine en essai à blanc (bloc par bloc, avance rapide réduite) ou dans un simulateur CN externe. La simulation ici ne le remplace pas – utilisation à vos propres risques, sans garantie.",
"⚠ Kollision bei {0} von {1} Stellungen, z. B. {2}":"⚠ Collision à {0} positions sur {1}, p. ex. {2}",
"⚠ Kreisbögen mit R statt I/J werden nicht unterstützt – I/J wird ausgegeben":"⚠ Les arcs avec R au lieu de I/J ne sont pas pris en charge – I/J est généré",
"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ Après la dernière modification du corps, l’arête ou la face concernée n’était plus identifiable sans ambiguïté. Veuillez vérifier – au besoin, supprimez et projetez à nouveau.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ La logique de programme (JavaScript) n'est pas exécutée : veuillez vérifier les fonctions spéciales, les 4e/5e axes, les cycles de palpage et les options machine dans l'éditeur de post-processeur.",
"⚠ {0} Abhängigkeit(en) nicht erfüllbar – Skizze überbestimmt oder widersprüchlich":"⚠ {0} contrainte(s) impossible(s) à satisfaire – esquisse sur-contrainte ou contradictoire",
