"✓ Keine Kollision im gesamten Bewegungsbereich":"✓ Aucune collision sur toute la plage de mouvement",
"✓ Keine Kollision mit dem Material (Halter, Schaft, Eilgänge){0} – Zeile für Zeile gegen das jeweils verbliebene Rohteil geprüft":"✓ Aucune collision avec la matière (porte-outil, queue, avances rapides){0} – contrôlé ligne par ligne par rapport au brut restant à ce moment",
"✓ Keine Überschneidungen zwischen den Körpern.":"✓ Aucune interférence entre les corps.",
"📚 = Bibliothek: eigene Postprozessoren stehen in allen Projekten zur Verfügung. Ein verwendeter wird ins Projekt kopiert, damit die Datei vollständig bleibt.":"📚 = bibliothèque : les post-processeurs personnels sont disponibles dans tous les projets. Celui qui est utilisé est copié dans le projet pour que le fichier reste complet.",
"📚 Die Bibliothek hat eine andere Fassung dieses Postprozessors.":"📚 La bibliothèque contient une autre version de ce post-processeur.",
"🔒 Eingebaute Maschine – zum Ändern duplizieren.":"🔒 Machine intégrée – la dupliquer pour la modifier.",
